import{z as n,x as s,o as r,c as p,q as t,j as i,D as e,d as l,s as A,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"可判定与可识别","description":"","frontmatter":{"title":"可判定与可识别","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/decidable-recognizable.md","filePath":"cs/decidable-recognizable.md","lastUpdated":1791413859000}'),d={name:"cs/decidable-recognizable.md"};function m(h,a,B,_,c,T){const E=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="可判定与可识别" tabindex="-1">可判定与可识别 <a class="header-anchor" href="#可判定与可识别" aria-label="Permalink to &quot;可判定与可识别&quot;">​</a></h1><div class="epigraph"><p>判定机对每个输入都停，回答是或否；识别机只保证是实例停下接受。递归可枚举可以不是递归。</p><footer>—— 据 Kleene；Sipser, Introduction to the Theory of Computation 整理</footer></div><p>上一课<a href="/cs/church-turing-thesis">Church–Turing 论题</a>把算法对齐到 TM。缺口是把语言分成两类：<strong>可判定（递归）<strong>与</strong>可识别（RE）</strong>。CYK 那一层全部可判定；本课给出定义、闭包与一张表：\\(A_{\\mathrm{TM}}\\) 将出现在下一课，这里先把格子画好。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TM 三种结局。判定器：无循环。识别器：是实例必接受停，否实例可循环。\\(L\\) 可判定 \\(\\Rightarrow\\) 可识别。反之否：下一课的停机语言可识别不可判定。补：可判定语言对补封闭（翻接受/拒绝）；RE 对补不封闭——若 \\(L\\) 与 \\(\\overline L\\) 都 RE，则 \\(L\\) 可判定（两边并行，总有一边停）。</p><p><span class="marginnote">术语翻译：可识别（RE）只承诺「答案是『是』时你终将等到点头」；答案是「否」时机器可能永远转下去。可判定则两边都给答案且必给——把识别器升级成判定器的全部难度，都压在那些「否」的实例上。</span></p><p>枚举器：可判定语言可按字典序无重复枚举；一般 RE 只能「有就终将打出」，顺序与重复不保证。</p><h3 id="递归不是「递归函数课」" tabindex="-1">递归不是「递归函数课」 <a class="header-anchor" href="#递归不是「递归函数课」" aria-label="Permalink to &quot;递归不是「递归函数课」&quot;">​</a></h3><p>递归语言 = 可判定语言，历史名称。一般递归函数对应全可计算函数。本课用判定/识别，避免与程序递归混淆。</p><p><span class="marginnote">Kleene 的层次与 Post 的定理：\\(L\\) 可判定 iff \\(L\\) 与补都 RE。Sipser 第 4 章把 \\(A_{\\mathrm{DFA}},A_{\\mathrm{CFG}}\\) 放在可判定，\\(A_{\\mathrm{TM}}\\) 放在可识别。本课点名这些例子，证明下一课才对角化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列一张表：DFA 空性、等价可判定；CFG 空性、成员可判定，等价不可判定（点名）；TM 成员不可判定。证明可判定：给总停算法。证明可识别：给识别器或枚举器。证明不可判定留给后课归约。</p>',12)),(r(),i(o,null,{default:e(()=>[A(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEC%5B%22%E5%8F%AF%E5%88%A4%E5%AE%9A%20%2F%20%E9%80%92%E5%BD%92%22%5D%20--%3E%20RE%5B%22%E5%8F%AF%E8%AF%86%E5%88%AB%20%2F%20RE%22%5D%0A%20%20RE%20--%3E%20ALL%5B%22%E6%89%80%E6%9C%89%E8%AF%AD%E8%A8%80%22%5D%0A%20%20DEC%20--%3E%20COMP%5B%22%E5%AF%B9%E8%A1%A5%E5%B0%81%E9%97%AD%22%5D%0A%20%20RE%20--%3E%20NOTC%5B%22%E5%AF%B9%E8%A1%A5%E4%B8%8D%E5%B0%81%E9%97%AD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>主干<a href="/cs/p-vs-np">P 与 NP</a> 谈的是时间；这里还没有钟。可判定可以极慢。不要把「有算法」写成多项式。</p><p><span class="marginnote">常见误区：初学者容易把「可判定」当成「实际算得动」。可判定只保证总停，可能要算 \\(10^{100}\\) 年；从「可判定」到「多项式时间」（P 与 NP 课的主干）隔着整整一层复杂度理论，本课的钟还没上发条。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>通用识别器：把 \\(\\langle M,w\\rangle\\) 交给通用 TM 模拟 \\(M\\) 在 \\(w\\) 上，接受则接受——于是 \\(A_{\\mathrm{TM}}=\\{\\langle M,w\\rangle\\mid M\\) 接受 \\(w\\}\\) 可识别。它是否可判定是下一课的对角化。有了通用机，机器本身成为串，自指才可能。</p><p><span class="marginnote">直觉类比：「两边并行」像同时面试两位候选人、每人轮流问一个问题——不偏向任何一方，谁先给结论就按谁的办。只闷头跑 \\(L\\) 那一个识别器，碰上「否」实例你会等一辈子；交错推进才保证总有一边先停。</span></p>',5)),(r(),i(o,null,{default:e(()=>[A(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%20w%22%5D%20--%3E%20A%5B%22%E8%AF%86%E5%88%AB%20L%20%E7%9A%84%E6%9C%BA%E5%99%A8%E8%B5%B0%E4%B8%80%E6%AD%A5%22%5D%0A%20%20IN%20--%3E%20B%5B%22%E8%AF%86%E5%88%AB%E8%A1%A5%20L%20%E7%9A%84%E6%9C%BA%E5%99%A8%E8%B5%B0%E4%B8%80%E6%AD%A5%22%5D%0A%20%20A%20--%3E%20Q%5B%22%E8%B0%81%E5%85%88%E6%8E%A5%E5%8F%97%22%5D%0A%20%20B%20--%3E%20Q%0A%20%20Q%20--%3E%20Y%5B%22L%20%E8%BE%B9%E8%B5%A2%EF%BC%9A%E6%8E%A5%E5%8F%97%20w%22%5D%0A%20%20Q%20--%3E%20N%5B%22%E8%A1%A5%E8%BE%B9%E8%B5%A2%EF%BC%9A%E6%8B%92%E7%BB%9D%20w%22%5D%0A%20%20Y%20--%3E%20TOT%5B%22%E6%80%BB%E6%9C%89%E4%B8%80%E8%BE%B9%E5%81%9C%EF%BC%9AL%20%E5%8F%AF%E5%88%A4%E5%AE%9A%22%5D%0A%20%20N%20--%3E%20TOT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>RE 对并、交、同态封闭；对补、全称量词不封闭。本课登记并与补这一对。</p><p>\\(A_{\\mathrm{DFA}}\\)、\\(E_{\\mathrm{DFA}}\\)、\\(EQ_{\\mathrm{DFA}}\\) 可判定，因为最小化或乘积补交有算法。\\(A_{\\mathrm{CFG}}\\) 可判定（CYK），\\(EQ_{\\mathrm{CFG}}\\) 不可判定。这张表说明：不可判定不是「机器变复杂就自动发生」，而是过了通用 TM 这一道。本课先把判定/识别的定义用熟。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证停机，不引入算术层级。不把递归可枚举说成「可列」：所有语言作为集合都可谈基数，\\(\\Sigma^*\\) 可数，语言可数或不可数是另一句。后课默认：判定 = 总停；识别 = RE。下一课对角化打 \\(A_{\\mathrm{TM}}\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>判定总停；识别只保证是实例停。</li><li>两边都 RE \\(\\Rightarrow\\) 可判定；RE 对补不封闭。</li><li>\\(A_{\\mathrm{TM}}\\) 可识别；是否可判定下一课。</li><li>出处：Kleene；Sipser。</li></ul>',6))])}const f=n(d,[["render",m]]);export{u as __pageData,f as default};
